import sys
from pathlib import Path
R=Path(__file__).resolve().parents[2];sys.path.insert(0,str(R))
from research.native_event_episode_context_v1.run import D,P,read,put,sha

def main():
 r=read(P/'report.json');s=read(D/'sealed.json');p=read(D/'plan.json');a=p['primary'];pair=r['paired'][a+'-NativeG6'];source=r['paired'][a+'-Source'];sg={name:{arm:sum(100*(x['values'][arm]['t']-x['values']['Source']['t'])for x in r['rows']if x['duration_group']==name)/sum(x['duration_group']==name for x in r['rows'])for arm in p['arms']}for name in r['groups_vs_G6']};put(P/'source_duration_groups.json',sg)
 passed=all(x['mean']>0 for x in [pair['t'],pair['v'],source['t'],source['v']])and pair['t']['improved']>pair['t']['harmed']and all(sg[x][a]>0 for x in sg)and all(r['paired'][a+'-'+b]['t']['mean']>0 for b in ['GlobalClauseFusion','EpisodeFullFusion','ShiftedEpisodeClauseFusion'])
 lines=['# Actual shared-episode positive event reading','','Exposed HC64 development, not independent confirmation. NativeG6 boundaries define a common at-least49-node window BEFORE actual positive first/last text-conditioned inference. No chronology constraint, likelihood ratio, query update or confidence rejection. All52 supported descriptions receive EpisodeFull/First/Last and matched-width shifted First/Last. Twelve unsupported descriptions remain native. Original visual feature values, global-offset positions, two-pass native inference, physical MBR and complete-box DP stay fixed. Cached motion still contains original clip context.','','Text encoding reused within query across context variants and explicitly counted. Odd-start windows reorder local parity while retaining original frame IDs/positions. All64 global Full text/hidden/posterior/Source boxes restore bitwise. Source/Native/archived GlobalClause aliases exact. All64 seal before independent CPU GT scoring.','','|Arm|complete vIoU|tIoU|time +/−/=|time harm>5pp|','|---|---:|---:|---:|---:|']
 for arm,m in r['means'].items():
  t=r['paired'].get(arm+'-NativeG6',{}).get('t',{});lines.append(f"|{arm}|{100*m['v']:.4f}|{100*m['t']:.4f}|{t.get('improved',0)}/{t.get('harmed',0)}/{t.get('unchanged',64)}|{t.get('severe_below_minus5pp',0)}|")
 lines +=['',f"Primary−G6 t{pair['t']['mean']:+.4f}pp CI{pair['t']['CI95']}, v{pair['v']['mean']:+.4f}pp CI{pair['v']['CI95']}; Source t{source['t']['mean']:+.4f}, v{source['v']['mean']:+.4f}pp.",f"Source shortt{sg['short_le5s'][a]:+.4f}pp; longt{sg['long_gt5s'][a]:+.4f}pp."]
 for b in ['GlobalClauseFusion','EpisodeFullFusion','EpisodeSelfHullFusion','ShiftedEpisodeClauseFusion','DirectEpisodeClauses']:lines.append(f"Primary−{b} t{r['paired'][a+'-'+b]['t']['mean']:+.4f}pp CI{r['paired'][a+'-'+b]['t']['CI95']}.")
 lines+=['','Basic development screen passes; fixed dual-domain recheck still required.'if passed else'Not qualified; no window/alpha scan or posthoc promotion of controls.',f"Worker {s['seconds']:.2f}s inclloading/research recording; calls{s['counts']}. This is not deployment end-to-end cost. Official/dense checks{r['checks']} maxerror{r['max_metric_error']:.3g}.",'','[Signed outcomes](signed.tsv), [severe declines](severe_declines.tsv), [Source groups](source_duration_groups.json), [protocol](protocol.json).']
 (P/'ANALYSIS.md').write_text('\n'.join(lines)+'\n');put(P/'verification.json',dict(queries=64,supported=52,Full_text_hidden_q_boxes_bitwise=64,global_clause_source_native_aliases_bitwise=64,paper_sources_unchanged=48,provider_sources_unchanged=434,odd_even_window_tests=True,all64_seal_before_GT=True,checks=r['checks'],max_metric_error=r['max_metric_error'],basic_development_screen=passed,promoted=False,seal_sha256=sha(D/'sealed.json')))
